    25→    use Chalk::IR::Node::PostIncrement;
    26→    use Chalk::IR::Node::PostDecrement;
    27→    use Chalk::IR::Node::Reference;
    28→    use Chalk::IR::Node::ScalarDeref;
    29→    use Chalk::IR::Node::VariableRead;
    30→    use Chalk::IR::Node::GT;
    31→    use Chalk::IR::Node::LT;
    32→    use Chalk::IR::Node::EQ;
    33→    use Chalk::IR::Node::NE;
    34→    use Chalk::IR::Node::LE;
    35→    use Chalk::IR::Node::GE;
    36→    use Chalk::IR::Node::If;
    37→    use Chalk::IR::Node::Proj;
    38→    use Chalk::IR::Node::Region;
    39→    use Chalk::IR::Node::Phi;
    40→    use Chalk::IR::Node::Loop;
    41→
    42→    field $graph :reader;
    43→    field $context :reader;  # Context-as-closure for variable memory
    44→    field $node_counter :reader = 0;
    45→    field $current_control :reader;  # Current control flow node
    46→    field $loop_depth = 0;   # Current loop nesting depth for label namespacing
    47→
    48→    ADJUST {
    49→        $graph = Chalk::IR::Graph->new();
    50→        $context = Chalk::IR::Context->empty_context();
    51→    }
    52→
    53→    # Generate unique node ID
    54→    method next_node_id() {
    55→        my $id = "node_$node_counter";
    56→        $node_counter++;
    57→        return $id;
    58→    }
    59→
    60→    # Set current control flow node
    61→    method set_control($ctrl) {
    62→        $current_control = $ctrl;
    63→    }
    64→
    65→    # Set context (for testing and manual context updates)
    66→    method set_context($ctx) {
    67→        $context = $ctx;
    68→    }
    69→
    70→    # Create Start node for a function/method
    71→    method build_start_node($function_name = 'main', $params = undef) {
    72→        $params //= [];
    73→        my $node_id = $self->next_node_id();
    74→        my $empty_inputs = [];
    75→        my $start = Chalk::IR::Node::Start->new(
    76→            id            => $node_id,
    77→            inputs        => $empty_inputs,
    78→            function_name => $function_name,
    79→            params        => $params,
    80→        );
    81→        $graph->add_node($start);
    82→        $self->set_control($start->id);
    83→
    84→        # Create Proj nodes for each parameter and register in context
    85→        my $param_count = scalar($params->@*);
    86→        for my $i (0..($param_count - 1)) {
    87→            my $param_name = $params->[$i];
    88→            my $proj = $self->build_proj_node($start, $i, $param_name);
    89→            # Register parameter Proj in context with lexical: namespace
    90→            my $label = "lexical:$param_name";
    91→            $context = Chalk::IR::Context->extend_context($context, $label, $proj);
    92→        }
    93→
    94→        return $start;
    95→    }
    96→
    97→    # Create Constant node
    98→    method build_constant_node($value, $type = 'Int') {
    99→        my $node_id = $self->next_node_id();
   100→        my $constant = Chalk::IR::Node::Constant->new(
   101→            id            => $node_id,
   102→            inputs        => [$current_control],
   103→            value         => $value,
   104→            type          => $type,
   105→        );
   106→        $graph->add_node($constant);
   107→        return $constant;
   108→    }
   109→
   110→    # Create Return node
   111→    # If $control is undef, uses current_control. Otherwise uses provided control.
   112→    method build_return_node($value_node, $control = undef) {
   113→        # Debug: check what we received
   114→        my $ref_type = ref($value_node) || 'SCALAR';
   115→        my $prefix = substr($ref_type, 0, 15);
   116→        my $is_node = ($prefix eq 'Chalk::IR::Node') ? 1 : 0;
   117→        unless ($ref_type && $is_node) {
   118→            warn "build_return_node received non-node: $ref_type\n";
   119→            return undef;
   120→        }
   121→
   122→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
   123→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
   124→
   125→        my $node_id = $self->next_node_id();
   126→        my $return = Chalk::IR::Node::Return->new(
   127→            id            => $node_id,
   128→            inputs        => [$ctrl, $value_node->id],
   129→            value_id      => $value_node->id,
   130→            control_id    => $ctrl,
   131→        );
   132→        $graph->add_node($return);
   133→        return $return;
   134→    }
   135→
   136→    # Set control input for an existing node
   137→    method set_node_control($node, $control_id) {
   138→        my $inputs = $node->inputs;
   139→        $inputs->[0] = $control_id;  # Control is always first input
   140→    }
   141→
   142→    # Create arithmetic operation nodes
   143→    method build_add_node($left_node, $right_node) {
   144→        my $node_id = $self->next_node_id();
   145→        my $add = Chalk::IR::Node::Add->new(
   146→            id => $node_id,
   147→            inputs => [$current_control, $left_node->id, $right_node->id],
   148→            left_id => $left_node->id,
   149→            right_id => $right_node->id,
   150→        );
   151→        $graph->add_node($add);
   152→        return $add;
   153→    }
   154→
   155→    method build_multiply_node($left_node, $right_node) {
   156→        my $node_id = $self->next_node_id();
   157→        my $mul = Chalk::IR::Node::Multiply->new(
   158→            id => $node_id,
   159→            inputs => [$current_control, $left_node->id, $right_node->id],
   160→            left_id => $left_node->id,
   161→            right_id => $right_node->id,
   162→        );
   163→        $graph->add_node($mul);
   164→        return $mul;
   165→    }
   166→
   167→    method build_sub_node($left_node, $right_node) {
   168→        my $node_id = $self->next_node_id();
   169→        my $sub = Chalk::IR::Node::Subtract->new(
   170→            id => $node_id,
   171→            inputs => [$current_control, $left_node->id, $right_node->id],
   172→            left_id => $left_node->id,
   173→            right_id => $right_node->id,
   174→        );
   175→        $graph->add_node($sub);
   176→        return $sub;
   177→    }
   178→
   179→    method build_divide_node($left_node, $right_node) {
   180→        my $node_id = $self->next_node_id();
   181→        my $div = Chalk::IR::Node::Divide->new(
   182→            id => $node_id,
   183→            inputs => [$current_control, $left_node->id, $right_node->id],
   184→            left_id => $left_node->id,
   185→            right_id => $right_node->id,
   186→        );
   187→        $graph->add_node($div);
   188→        return $div;
   189→    }
   190→
   191→    # Generate label with loop depth if inside a loop
   192→    method make_variable_label($var_name) {
   193→        if ($loop_depth > 0) {
   194→            return "lexical:loop_" . ($loop_depth - 1) . ":$var_name";
   195→        }
   196→        return "lexical:$var_name";
   197→    }
   198→
   199→    # Create Store node (variable assignment)
   200→    method build_store_node($var_name, $value_node, $control = undef) {
   201→        # Store variable using lexical: namespace in context
   202→        # Inside loops, use loop depth in label: lexical:loop_0:$var
   203→        # Store the IR node object directly, not the node ID
   204→        my $label = $self->make_variable_label($var_name);
   205→        $context = Chalk::IR::Context->extend_context($context, $label, $value_node);
   206→
   207→        return $value_node;
   208→    }
   209→
   210→    # Load node (variable read)
   211→    method build_load_node($var_name) {
   212→        # Retrieve variable using lexical: namespace from context
   213→        # Try loop-scoped label first, then fall back to outer scope
   214→        # Context now stores IR node objects directly, not node IDs
   215→        my $node;
   216→
   217→        # Try current loop depth first (search from innermost to outermost)
   218→        if ($loop_depth > 0) {
   219→            my $depth = $loop_depth - 1;
   220→            while ($depth >= 0) {
   221→                my $label = "lexical:loop_${depth}:$var_name";
   222→                $node = $context->($label);
   223→                last if defined $node;
   224→                $depth--;
   225→            }
   226→        }
   227→
   228→        # Fall back to non-loop lexical scope
   229→        $node //= $context->("lexical:$var_name");
   230→
   231→        # Return the node directly from context (no graph lookup needed)
   232→        return $node;
   233→    }
   234→
   235→    # Create Proj node (projection from MultiNode like Start)
   236→    method build_proj_node($source_node, $index, $label) {
   237→        my $node_id = $self->next_node_id();
   238→        my $proj = Chalk::IR::Node::Proj->new(
   239→            id            => $node_id,
   240→            inputs        => [$source_node->id],
   241→            index         => $index,
   242→            label         => $label,
   243→        );
   244→        $graph->add_node($proj);
   245→        return $proj;
   246→    }
   247→
   248→    # Comparison nodes
   249→    method build_greater_node($left_node, $right_node) {
   250→        my $node_id = $self->next_node_id();
   251→        my $cmp = Chalk::IR::Node::GT->new(
   252→            id            => $node_id,
   253→            inputs        => [$current_control, $left_node->id, $right_node->id],
   254→            left_id       => $left_node->id,
   255→            right_id      => $right_node->id,
   256→        );
   257→        $graph->add_node($cmp);
   258→        return $cmp;
   259→    }
   260→
