   262→        my $node_id = $self->next_node_id();
   263→        my $cmp = Chalk::IR::Node::LT->new(
   264→            id            => $node_id,
   265→            inputs        => [$current_control, $left_node->id, $right_node->id],
   266→            left_id       => $left_node->id,
   267→            right_id      => $right_node->id,
   268→        );
   269→        $graph->add_node($cmp);
   270→        return $cmp;
   271→    }
