   286→        my $node_id = $self->next_node_id();
   287→        my $cmp = Chalk::IR::Node::GE->new(
   288→            id            => $node_id,
   289→            inputs        => [$current_control, $left_node->id, $right_node->id],
   290→            left_id       => $left_node->id,
   291→            right_id      => $right_node->id,
   292→        );
