   298→        my $node_id = $self->next_node_id();
   299→        my $cmp = Chalk::IR::Node::LE->new(
   300→            id            => $node_id,
   301→            inputs        => [$current_control, $left_node->id, $right_node->id],
   302→            left_id       => $left_node->id,
