   308→
   309→    method build_not_equal_node($left_node, $right_node) {
   310→        my $node_id = $self->next_node_id();
   311→        my $cmp = Chalk::IR::Node::NE->new(
   312→            id            => $node_id,
   313→            inputs        => [$current_control, $left_node->id, $right_node->id],
   314→            left_id       => $left_node->id,
   315→            right_id      => $right_node->id,
   316→        );
   317→        $graph->add_node($cmp);
