   320→
   321→    # Unary operation nodes
   322→    method build_not_node($operand_node) {
   323→        my $node_id = $self->next_node_id();
   324→        my $not = Chalk::IR::Node::Not->new(
   325→            id            => $node_id,
   326→            inputs        => [$current_control, $operand_node->id],
   327→            operand_id    => $operand_node->id,
   328→        );
   329→        $graph->add_node($not);
   330→        return $not;
