   334→        my $node_id = $self->next_node_id();
   335→        my $negate = Chalk::IR::Node::Negate->new(
   336→            id            => $node_id,
   337→            inputs        => [$current_control, $operand_node->id],
   338→            operand_id    => $operand_node->id,
