   344→    method build_pre_increment_node($operand_node) {
   345→        my $node_id = $self->next_node_id();
   346→        my $pre_inc = Chalk::IR::Node::PreIncrement->new(
   347→            id            => $node_id,
   348→            inputs        => [$current_control, $operand_node->id],
   349→            operand_id    => $operand_node->id,
