   388→    # OLD: This will be removed - use build_scalar_ref_node instead
   389→    method build_reference_node($operand_node) {
   390→        my $node_id = $self->next_node_id();
   391→        my $reference = Chalk::IR::Node::Reference->new(
   392→            id            => $node_id,
   393→            inputs        => [$current_control],
   394→            target_context => $context,  # Current context
   395→            target_label   => 'UNKNOWN',  # This is deprecated
   396→        );
   397→        $graph->add_node($reference);
   398→        return $reference;
