   401→    # Control flow nodes
   402→    method build_if_node($condition_node) {
   403→        my $node_id = $self->next_node_id();
   404→        my $if_node = Chalk::IR::Node::If->new(
   405→            id            => $node_id,
   406→            inputs        => [$current_control, $condition_node->id],
