   433→    method build_phi_node($region_node, @value_inputs) {
   434→        my $node_id = $self->next_node_id();
   435→        my $phi = Chalk::IR::Node::Phi->new(
   436→            id            => $node_id,
   437→            inputs        => [$region_node->id, @value_inputs],
