   443→
   444→    # Loop control flow nodes
   445→    method build_loop_node($entry_control = undef) {
   446→        my $ctrl = $entry_control // $current_control // '__CONTROL_PLACEHOLDER__';
   447→        my $node_id = $self->next_node_id();
   448→        my $loop = Chalk::IR::Node::Loop->new(
   449→            id            => $node_id,
   450→            inputs        => [$ctrl],  # Entry control; backedge added later
   451→        );
   452→        $graph->add_node($loop);
   453→        return $loop;
   454→    }
   455→
   456→    method build_loop_phi_node($loop_node, $initial_value, $loop_value = undef) {
   457→        # Loop phi starts with control and initial value
   458→        # Loop value added later (lazy phi pattern)
   459→        my @inputs = ($loop_node->id, $initial_value);
   460→        push @inputs, $loop_value if defined $loop_value;
   461→
   462→        my $node_id = $self->next_node_id();
   463→        my $phi = Chalk::IR::Node::Phi->new(
   464→            id            => $node_id,
   465→            inputs        => \@inputs,
   466→            region_id     => $loop_node->id,
   467→        );
   468→        $graph->add_node($phi);
   469→        return $phi;
   470→    }
   471→
   472→    # Function call nodes
   473→    method build_call_node($function_name, @arg_nodes) {
   474→        # Call: control, memory, arguments...
   475→        # For now, use current_control for both control and memory
   476→        my $attributes = { function => $function_name };
   477→        my $node_id = $self->next_node_id();
   478→        my $call = Chalk::IR::Node->new(
   479→            id            => $node_id,
   480→            op            => 'Call',
   481→            inputs        => [$current_control, $current_control, map { $_->id } @arg_nodes],
   482→            attributes    => $attributes,
   483→        );
   484→        $graph->add_node($call);
   485→        return $call;
   486→    }
   487→
   488→    # Loop depth tracking methods
   489→    method begin_loop_tracking() {
   490→        # Increment loop depth when entering a loop
   491→        $loop_depth++;
   492→        return;
   493→    }
   494→
   495→    method end_loop_tracking() {
   496→        # Decrement loop depth when exiting a loop
   497→        $loop_depth-- if $loop_depth > 0;
   498→        return;
   499→    }
   500→
   501→    method is_tracking_loop() {
   502→        return $loop_depth > 0;
   503→    }
   504→
   505→    method current_loop_depth() {
   506→        return $loop_depth;
   507→    }
   508→
   509→    method generate_loop_phi_nodes($loop_node) {
   510→        # Generate phi nodes for variables modified within the loop
   511→        # With context+labels approach, phi nodes are created for variables
   512→        # that exist both as 'lexical:$var' (pre-loop) and 'lexical:loop_N:$var' (in-loop)
   513→
   514→        # For now, return empty hash - full implementation will search context
   515→        # for labels matching the current loop depth pattern
   516→        return {};
   517→    }
   518→
   519→    # Class and object support nodes (Issue #98 Phase 1)
   520→
   521→    method build_classdef_node($class_name, $fields) {
   522→        # Create ClassDef node for class definition
   523→        my $attributes = {
   524→            name => $class_name,
   525→            fields => $fields,
   526→        };
   527→        my $node_id = $self->next_node_id();
   528→        my $classdef = Chalk::IR::Node->new(
   529→            id            => $node_id,
   530→            op            => 'ClassDef',
   531→            inputs        => [$current_control],
   532→            attributes    => $attributes,
   533→        );
   534→        $graph->add_node($classdef);
   535→        return $classdef;
   536→    }
   537→
   538→    method build_new_node($class_name, $field_values_hash) {
   539→        # Create New node for object instantiation
   540→        # $field_values_hash is a hashref mapping field names to node objects
   541→        my @input_nodes = ($current_control);
   542→        my %field_value_refs;
   543→
   544→        # Build field references from hash
   545→        for my $field_name (sort( keys( $field_values_hash->%* ) )) {
   546→            my $value_node = $field_values_hash->{$field_name};
   547→            push @input_nodes, $value_node->id;
   548→            $field_value_refs{$field_name} = {
   549→                op => 'NodeRef',
   550→                node_id => $value_node->id
   551→            };
   552→        }
   553→
   554→        my $attributes = {
   555→            class => $class_name,
   556→            field_values => \%field_value_refs
   557→        };
   558→        my $node_id = $self->next_node_id();
   559→        my $new_obj = Chalk::IR::Node->new(
   560→            id            => $node_id,
   561→            op            => 'New',
   562→            inputs        => \@input_nodes,
   563→            attributes    => $attributes,
   564→        );
   565→        $graph->add_node($new_obj);
   566→        return $new_obj;
   567→    }
   568→
   569→    method build_field_access_node($object_node, $field_name) {
   570→        # Create FieldAccess node for reading a field
   571→        my $object_ref = { op => 'NodeRef', node_id => $object_node->id };
   572→        my $attributes = {
   573→            field => $field_name,
   574→            object => $object_ref
   575→        };
   576→        my $node_id = $self->next_node_id();
