   653→    method build_array_set_node($array_node, $index_node, $value_node) {
   654→        # Create ArraySet node for setting array element with context extension (immutable)
   655→        my $node_id = $self->next_node_id();
   656→        my $array_set = Chalk::IR::Node::ArraySet->new(
   657→            id => $node_id,
   658→            inputs => [$current_control, $array_node->id, $index_node->id, $value_node->id],
