   684→    # Hash operations (Issue #98 Phase 3)
   685→    method build_hash_new_node() {
   686→        # Create HashNew node for creating an empty hash
   687→        my $node_id = $self->next_node_id();
   688→        my $hash_new = Chalk::IR::Node->new(
   689→            id => $node_id,
   690→            op => 'HashNew',
   691→            inputs => [$current_control],
   692→            attributes => {},
   693→        );
   694→        $graph->add_node($hash_new);
   695→        return $hash_new;
   696→    }
   697→
   698→    method build_hash_set_node($hash_node, $key_node, $value_node) {
   699→        # Create HashSet node for setting hash value with context extension (immutable)
   700→        my $node_id = $self->next_node_id();
   701→        my $hash_set = Chalk::IR::Node::HashSet->new(
   702→            id => $node_id,
   703→            inputs => [$current_control, $hash_node->id, $key_node->id, $value_node->id],
   704→            hash_id => $hash_node->id,
   705→            key_id => $key_node->id,
   706→            value_id => $value_node->id,
   707→        );
   708→        $graph->add_node($hash_set);
   709→        return $hash_set;
   710→    }
   711→
   712→    method build_hash_get_node($hash_node, $key_node) {
   713→        # Create HashGet node for accessing hash value by key using context lookup
   714→        my $node_id = $self->next_node_id();
   715→        my $hash_get = Chalk::IR::Node::HashGet->new(
   716→            id => $node_id,
   717→            inputs => [$current_control, $hash_node->id, $key_node->id],
   718→            hash_id => $hash_node->id,
   719→            key_id => $key_node->id,
   720→        );
   721→        $graph->add_node($hash_get);
   722→        return $hash_get;
   723→    }
   724→
   725→    method build_hash_exists_node($hash_node, $key_node) {
   726→        # Create HashExists node for checking if key exists in hash
   727→        my $hash_ref = { op => 'NodeRef', node_id => $hash_node->id };
   728→        my $key_ref = { op => 'NodeRef', node_id => $key_node->id };
   729→        my $attributes = {
   730→            hash => $hash_ref,
   731→            key => $key_ref
   732→        };
   733→        my $node_id = $self->next_node_id();
   734→        my $hash_exists = Chalk::IR::Node->new(
   735→            id => $node_id,
   736→            op => 'HashExists',
   737→            inputs => [$current_control, $hash_node->id, $key_node->id],
   738→            attributes => $attributes,
   739→        );
   740→        $graph->add_node($hash_exists);
   741→        return $hash_exists;
   742→    }
   743→
   744→    method build_hash_keys_node($hash_node) {
   745→        # Create HashKeys node for getting all keys from hash
   746→        my $hash_ref = { op => 'NodeRef', node_id => $hash_node->id };
   747→        my $attributes = {
   748→            hash => $hash_ref
   749→        };
   750→        my $node_id = $self->next_node_id();
   751→        my $hash_keys = Chalk::IR::Node->new(
   752→            id => $node_id,
   753→            op => 'HashKeys',
   754→            inputs => [$current_control, $hash_node->id],
   755→            attributes => $attributes,
   756→        );
   757→        $graph->add_node($hash_keys);
   758→        return $hash_keys;
