   760→
   761→    # String operations (Issue #98 Phase 4)
   762→    method build_str_concat_node($left_node, $right_node) {
   763→        # Create StrConcat node for concatenating two strings
   764→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   765→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   766→
   767→        my $attributes = {
   768→            left => $left_ref,
   769→            right => $right_ref
   770→        };
   771→
   772→        my $node_id = $self->next_node_id();
   773→        my $str_concat = Chalk::IR::Node->new(
   774→            id => $node_id,
   775→            op => 'StrConcat',
   776→            inputs => [$current_control, $left_node->id, $right_node->id],
   777→            attributes => $attributes,
   778→        );
   779→        $graph->add_node($str_concat);
   780→        return $str_concat;
   781→    }
   782→
   783→    # Range operations (Issue #111)
   784→    method build_range_node($start_node, $end_node, $type = 'list') {
   785→        # Create Range node for generating a range between start and end values
   786→        my $start_ref = { op => 'NodeRef', node_id => $start_node->id };
   787→        my $end_ref = { op => 'NodeRef', node_id => $end_node->id };
   788→
   789→        my $attributes = {
   790→            start => $start_ref,
   791→            end => $end_ref,
   792→            type => $type,
   793→        };
   794→
   795→        my $node_id = $self->next_node_id();
   796→        my $range = Chalk::IR::Node->new(
   797→            id => $node_id,
   798→            op => 'Range',
   799→            inputs => [$current_control, $start_node->id, $end_node->id],
   800→            attributes => $attributes,
   801→        );
   802→        $graph->add_node($range);
   803→        return $range;
   804→    }
   805→
   806→    method build_str_length_node($string_node) {
   807→        # Create StrLength node for getting string length
   808→        my $string_ref = { op => 'NodeRef', node_id => $string_node->id };
   809→
   810→        my $attributes = {
   811→            string => $string_ref
   812→        };
   813→
   814→        my $node_id = $self->next_node_id();
   815→        my $str_length = Chalk::IR::Node->new(
   816→            id => $node_id,
   817→            op => 'StrLength',
   818→            inputs => [$current_control, $string_node->id],
   819→            attributes => $attributes,
   820→        );
   821→        $graph->add_node($str_length);
   822→        return $str_length;
   823→    }
   824→
   825→    method build_str_substr_node($string_node, $offset_node, $length_node) {
   826→        # Create StrSubstr node for extracting substring
   827→        my $string_ref = { op => 'NodeRef', node_id => $string_node->id };
   828→        my $offset_ref = { op => 'NodeRef', node_id => $offset_node->id };
   829→        my $length_ref = { op => 'NodeRef', node_id => $length_node->id };
   830→
   831→        my $attributes = {
   832→            string => $string_ref,
   833→            offset => $offset_ref,
   834→            length => $length_ref
   835→        };
   836→
   837→        my $node_id = $self->next_node_id();
   838→        my $str_substr = Chalk::IR::Node->new(
   839→            id => $node_id,
   840→            op => 'StrSubstr',
   841→            inputs => [$current_control, $string_node->id, $offset_node->id, $length_node->id],
   842→            attributes => $attributes,
   843→        );
   844→        $graph->add_node($str_substr);
   845→        return $str_substr;
   846→    }
   847→
   848→    # Module system support (Issue #98 Phase 5)
   849→    method build_use_statement_node($type, $module, $imports) {
   850→        # Create UseStatement node for capturing use statement metadata
   851→        # $type: 'version', 'pragma', 'module', or 'external'
   852→        # $module: module name (e.g., '5.42.0', 'experimental', 'Chalk::IR::Node')
   853→        # $imports: arrayref of imported symbols (empty for full import)
   854→
   855→        my $graph = $self->graph;
   856→        my $current_control = $self->current_control;
   857→
   858→        my $attributes = {
   859→            type => $type,
   860→            module => $module,
   861→            imports => $imports
   862→        };
   863→
   864→        my $node_id = $self->next_node_id();
   865→        my $use_stmt = Chalk::IR::Node->new(
   866→            id => $node_id,
   867→            op => 'UseStatement',
   868→            inputs => [$current_control],
   869→            attributes => $attributes,
   870→        );
   871→        $graph->add_node($use_stmt);
   872→        return $use_stmt;
   873→    }
   874→
   875→    # Reference operations (Issue #130 Phase 4)
   876→
   877→    # Create reference to a scalar variable: \$x
   878→    method build_scalar_ref_node($var_name) {
   879→        my $label = "lexical:$var_name";
   880→        # Look up the target node (might be object or ID)
   881→        my $target_node_or_id = $context->($label);
   882→        die "Cannot create reference to undefined variable $var_name" unless defined $target_node_or_id;
   883→
   884→        # Get the node ID for the dependency
   885→        my $target_node_id = ref($target_node_or_id) ? $target_node_or_id->id : $target_node_or_id;
   886→
   887→        my $node_id = $self->next_node_id();
   888→        my $reference = Chalk::IR::Node::Reference->new(
   889→            id             => $node_id,
   890→            inputs         => [$current_control, $target_node_id],  # Add target as dependency
   891→            target_context => $context,
   892→            target_label   => $label,
   893→        );
   894→        $graph->add_node($reference);
   895→        return $reference;
   896→    }
   897→
   898→    # Create reference to array element: \$arr[1]
   899→    method build_element_ref_node($collection_name, $index_node) {
   900→        # Get the collection from context (might be object or ID)
   901→        my $collection_label = "lexical:$collection_name";
   902→        my $collection_node_or_id = $context->($collection_label);
   903→
   904→        # Get the collection node
   905→        my $collection_node;
   906→        if (ref($collection_node_or_id)) {
   907→            $collection_node = $collection_node_or_id;
   908→        } else {
   909→            $collection_node = $graph->get_node($collection_node_or_id);
   910→        }
   911→
   912→        # Get the array context from the collection node
   913→        my $array_ctx = $collection_node->array_context;
   914→
   915→        # Get the index value - need to evaluate it
   916→        # For now, assume it's a constant node
   917→        my $index_val = $index_node->value;
   918→
   919→        # Create the reference pointing to the array context with index: label
   920→        my $label = Chalk::IR::Context->make_index_label($index_val);
   921→        my $node_id = $self->next_node_id();
   922→        my $reference = Chalk::IR::Node::Reference->new(
   923→            id             => $node_id,
   924→            inputs         => [$current_control, $collection_node->id, $index_node->id],
   925→            target_context => $array_ctx,
   926→            target_label   => $label,
   927→        );
   928→        $graph->add_node($reference);
   929→        return $reference;
   930→    }
   931→
   932→    # Dereference a scalar reference: $$ref
   933→    method build_scalar_deref_node($ref_var_name) {
   934→        # Get the reference from context (might be object or ID)
   935→        my $ref_label = "lexical:$ref_var_name";
   936→        my $ref_node_or_id = $context->($ref_label);
   937→
   938→        # Get the node ID
   939→        my $ref_id = ref($ref_node_or_id) ? $ref_node_or_id->id : $ref_node_or_id;
   940→
   941→        # Create ScalarDeref node
   942→        my $node_id = $self->next_node_id();
   943→        my $deref = Chalk::IR::Node::ScalarDeref->new(
   944→            id      => $node_id,
   945→            inputs  => [$current_control, $ref_id],
   946→            ref_id  => $ref_id,
   947→        );
   948→        $graph->add_node($deref);
   949→        return $deref;
   950→    }
   951→
   952→    # Read variable from context: helper for tests
   953→    method build_variable_read_node($var_name) {
   954→        my $label = "lexical:$var_name";
   955→        my $node_id = $self->next_node_id();
   956→        my $var_read = Chalk::IR::Node::VariableRead->new(
   957→            id        => $node_id,
   958→            inputs    => [$current_control],
   959→            var_label => $label,
   960→        );
   961→        $graph->add_node($var_read);
   962→        return $var_read;
   963→    }
   964→
   965→    # Assign through a dereferenced reference: $$ref = value
   966→    method build_scalar_deref_assign_node($ref_var_name, $value_node) {
   967→        # Get the reference from context
   968→        my $ref_label = "lexical:$ref_var_name";
   969→        my $ref_node_or_id = $context->($ref_label);
   970→
   971→        # Might be node object or node ID depending on when it was stored
   972→        my $ref_node;
   973→        if (ref($ref_node_or_id)) {
   974→            $ref_node = $ref_node_or_id;
   975→        } else {
   976→            $ref_node = $graph->get_node($ref_node_or_id);
   977→        }
   978→
   979→        # Get the target label from the reference
   980→        my $target_label = $ref_node->target_label;
   981→
   982→        # Extend the BUILDER's current context with the new value (node object, not ID)
   983→        # This updates the variable that the reference points to
   984→        $context = Chalk::IR::Context->extend_context(
   985→            $context,
   986→            $target_label,
   987→            $value_node
   988→        );
   989→
   990→        # Return the value node for chaining
   991→        return $value_node;
   992→    }
   993→
   994→}
   995→
   996→1;
