    ok $builder->is_tracking_loop(), 'Loop tracking active';

    # Get snapshot
    my $entry_scope = $builder->loop_entry_scope();
    ok $entry_scope, 'Entry scope captured';
    is $entry_scope->{i}, 'initial_i', 'Initial binding for i captured';
};

