    $scope->define('i', $i_update->id);

    my $phis = $builder->generate_loop_phi_nodes($loop);

    ok exists($phis->{i}), 'Phi for modified variable i';
    ok !exists($phis->{limit}), 'No phi for unmodified variable limit';
};

