#!/usr/bin/env perl
# Test phi node generation with context model
use 5.42.0;
use lib 'lib';
use Chalk::IR::Builder;

my $builder = Chalk::IR::Builder->new();
my $start = $builder->build_start_node();

# Initialize variable before loop
my $init_val = $builder->build_constant_node(0);
$builder->build_store_node('x', $init_val);

print "Pre-loop: stored x = 0\n";
print "Context lookup for 'lexical:x': ", ($builder->context->('lexical:x') ? "found" : "not found"), "\n";

# Begin loop
$builder->begin_loop_tracking();
print "\nLoop depth: ", $builder->current_loop_depth(), "\n";

my $loop = $builder->build_loop_node();

# Modify variable inside loop
my $new_val = $builder->build_constant_node(1);
$builder->build_store_node('x', $new_val);

print "Inside loop: stored x = 1\n";
print "Context lookup for 'lexical:loop_0:x': ", ($builder->context->('lexical:loop_0:x') ? "found" : "not found"), "\n";

# Generate phi nodes
my $phis = $builder->generate_loop_phi_nodes($loop);

print "\nPhi nodes generated: ", scalar(keys %$phis), "\n";

if (exists $phis->{x}) {
    my $phi = $phis->{x};
    print "Phi for 'x' created:\n";
    print "  - op: ", $phi->op, "\n";
    print "  - inputs: ", scalar(@{$phi->inputs}), "\n";
    print "  - control: ", $phi->inputs->[0], "\n";
    print "  - initial value: ", $phi->inputs->[1], "\n";
    print "  - loop value: ", $phi->inputs->[2], "\n";
} else {
    print "ERROR: No phi generated for x!\n";
    exit 1;
}

$builder->end_loop_tracking();

print "\nPhi node generation successful!\n";

